1	/**
2	 * Game state: the phases, the inputs, and how a game starts.
3	 *
4	 * The state is a **discriminated union over `phase`**, not a bag of optional
5	 * fields. A `ResolvingState` has no `piece`, so nothing can move a piece
6	 * during a chain; a `FallingState` has no `result`, so nothing can advance a
7	 * chain while the player is in control. The reducer narrows on `phase` once
8	 * and hands the narrowed state to a handler typed to accept only that phase —
9	 * an illegal input in a phase is not ignored at runtime, it does not typecheck.
10	 *
11	 * Time is an input. Nothing in this directory reads `Date.now`,
12	 * `performance.now`, `setTimeout` or `requestAnimationFrame`.
13	 */
14	
15	import {
16	  HEIGHT,
17	  HIDDEN_ROWS,
18	  WIDTH,
19	  createBoard,
20	  type Board,
21	  type Color,
22	  type ResolveResult,
23	} from '../core/index.js';
24	import type { Piece } from './piece.js';
25	import { createQueue, type PieceQueue } from './queue.js';
26	
27	/** Tunables. Durations are milliseconds of *input* time, never wall clock. */
28	export interface GameConfig {
29	  readonly width: number;
30	  readonly height: number;
31	  /** Rows at the top that never pop and never form groups. */
32	  readonly hiddenRows: number;
33	  /** The column a pair spawns in — the one that decides game over. */
34	  readonly spawnX: number;
35	  /** Row of the axis at spawn; the child spawns directly above it. */
36	  readonly spawnY: number;
37	  /** Milliseconds per row of natural falling. */
38	  readonly fallIntervalMs: number;
39	  /** Grace period between the piece grounding and it locking. 0 = instant. */
40	  readonly lockDelayMs: number;
41	  /** Milliseconds each chain step is held before the next one pops. */
42	  readonly chainStepMs: number;
43	  /** Pause between a chain finishing and the next pair appearing. */
44	  readonly spawnDelayMs: number;
45	}
46	
47	export const DEFAULT_CONFIG: GameConfig = {
48	  width: WIDTH,
49	  height: HEIGHT,
50	  hiddenRows: HIDDEN_ROWS,
51	  // Third column, as in the real game. With HIDDEN_ROWS = 1 the axis spawns on
52	  // the first visible row and the child sits in the hidden row above it.
53	  spawnX: 2,
54	  spawnY: HIDDEN_ROWS,
55	  fallIntervalMs: 800,
56	  lockDelayMs: 500,
57	  chainStepMs: 300,
58	  spawnDelayMs: 0,
59	};
60	
61	/** Running totals a UI or a scorer can read off the state. */
62	export interface Stats {
63	  readonly piecesPlaced: number;
64	  /** Number of locks that popped at least one group. */
65	  readonly chains: number;
66	  readonly longestChain: number;
67	  readonly totalCleared: number;
68	}
69	
70	export const EMPTY_STATS: Stats = {
71	  piecesPlaced: 0,
72	  chains: 0,
73	  longestChain: 0,
74	  totalCleared: 0,
75	};
76	
77	/** The fields every phase carries. `baseOf` in `step.ts` copies exactly these. */
78	export interface GameCommon {
79	  readonly config: GameConfig;
80	  readonly board: Board;
81	  readonly queue: PieceQueue;
82	  /** Sum of every tick fed in so far. Derived from inputs, not from a clock. */
83	  readonly elapsedMs: number;
84	  readonly stats: Stats;
85	  /** The result of the most recent lock, for scoring and rendering. */
86	  readonly lastResolve: ResolveResult | null;
87	}
88	
89	/** Waiting to put the next pair on the board. */
90	export interface SpawningState extends GameCommon {
91	  readonly phase: 'spawning';
92	  /** Milliseconds waited so far, against `config.spawnDelayMs`. */
93	  readonly sinceMs: number;
94	}
95	
96	/** The player is in control and the pair still has room below it. */
97	export interface FallingState extends GameCommon {
98	  readonly phase: 'falling';
99	  readonly piece: Piece;
100	  /** Milliseconds accumulated toward the next row of natural falling. */
101	  readonly fallAccMs: number;
102	}
103	
104	/** The pair is resting; the player still has `lockDelayMs` to act. */
105	export interface LockingState extends GameCommon {
106	  readonly phase: 'locking';
107	  readonly piece: Piece;
108	  readonly fallAccMs: number;
109	  /** Milliseconds accumulated toward locking. */
110	  readonly lockAccMs: number;
111	}
112	
113	/** A chain is playing out, one step at a time. No piece exists. */
114	export interface ResolvingState extends GameCommon {
115	  readonly phase: 'resolving';
116	  readonly result: ResolveResult;
117	  /** How many of `result.steps` have been shown. `board` matches. */
118	  readonly stepIndex: number;
119	  readonly sinceMs: number;
120	}
121	
122	export type GameOverReason = 'spawn-blocked';
123	
124	/** Terminal. Every input is a no-op from here. */
125	export interface GameOverState extends GameCommon {
126	  readonly phase: 'gameover';
127	  readonly reason: GameOverReason;
128	  /** The pair that could not be placed, for a "you died here" overlay. */
129	  readonly blockedPiece: Piece;
130	}
131	
132	/** The phases in which player actions mean anything. */
133	export type ControllableState = FallingState | LockingState;
134	
135	export type GameState =
136	  | SpawningState
137	  | FallingState
138	  | LockingState
139	  | ResolvingState
140	  | GameOverState;
141	
142	/** A slice of elapsed time. The only way the world advances on its own. */
143	export interface TickInput {
144	  readonly type: 'tick';
145	  /** Milliseconds since the last tick. Must be finite and >= 0. */
146	  readonly ms: number;
147	}
148	
149	export type PlayerActionType =
150	  | 'moveLeft'
151	  | 'moveRight'
152	  | 'rotateCW'
153	  | 'rotateCCW'
154	  | 'softDrop'
155	  | 'hardDrop';
156	
157	export interface PlayerAction {
158	  readonly type: PlayerActionType;
159	}
160	
161	export type Input = TickInput | PlayerAction;
162	
163	/** `{ type: 'tick', ms }`. */
164	export function tick(ms: number): TickInput {
165	  return { type: 'tick', ms };
166	}
167	
168	/** `{ type }` for a player action, so tests read as `step(s, action('hardDrop'))`. */
169	export function action(type: PlayerActionType): PlayerAction {
170	  return { type };
171	}
172	
173	export const MOVE_LEFT: PlayerAction = { type: 'moveLeft' };
174	export const MOVE_RIGHT: PlayerAction = { type: 'moveRight' };
175	export const ROTATE_CW: PlayerAction = { type: 'rotateCW' };
176	export const ROTATE_CCW: PlayerAction = { type: 'rotateCCW' };
177	export const SOFT_DROP: PlayerAction = { type: 'softDrop' };
178	export const HARD_DROP: PlayerAction = { type: 'hardDrop' };
179	
180	export interface NewGameOptions {
181	  /** Injected randomness for the queue. Required — there is no default. */
182	  readonly rng: () => number;
183	  readonly config?: Partial<GameConfig>;
184	  readonly colors?: readonly Color[];
185	  readonly previewSize?: number;
186	  /** Start from an existing board, e.g. a test fixture. Defaults to empty. */
187	  readonly board?: Board;
188	}
189	
190	/**
191	 * A new game, in the `spawning` phase: the first pair appears on the first
192	 * tick, because nothing in this module happens without an input.
193	 */
194	export function createGame(options: NewGameOptions): SpawningState {
195	  const config: GameConfig = { ...DEFAULT_CONFIG, ...options.config };
196	  const board = options.board ?? createBoard(config.width, config.height);
197	  const queue = createQueue(options.rng, {
198	    ...(options.colors === undefined ? {} : { colors: options.colors }),
199	    ...(options.previewSize === undefined ? {} : { previewSize: options.previewSize }),
200	  });
201	  return {
202	    phase: 'spawning',
203	    config,
204	    board,
205	    queue,
206	    elapsedMs: 0,
207	    stats: EMPTY_STATS,
208	    lastResolve: null,
209	    sinceMs: 0,
210	  };
211	}
212	
213	/** The piece the player controls, if there is one right now. */
214	export function activePiece(state: GameState): Piece | null {
215	  return state.phase === 'falling' || state.phase === 'locking' ? state.piece : null;
216	}
217	
218	/** Is the game over? */
219	export function isGameOver(state: GameState): state is GameOverState {
220	  return state.phase === 'gameover';
221	}
